    editIncident: function() {
        var selections = this.getSelectionModel().getSelections();

        if(selections.length > 0) {
            this.updateItem(selections[0]);
        }
        else
            Ext.Msg.show({
                title: 'Atender Incidente',
                msg: 'Primeiro selecione o incidente que você deseja atender.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
    },

    receive_incident: function(oId) {
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Recebendo...'});

        mask.show();
        this.factoryRestful().receive(
            oId,
            {
                scope: this,
                fn: function(obj) {}
            },
            {
                scope: this,
                fn: function(message) {}
            },
            {
                scope: this,
                fn: function() {
                    mask.hide();
                }
            }
        );
    },

    updateItem: function() {
        var selections = this.getSelectionModel().getSelections();
        record = selections[0];
        if (!record.get('is_received')) {
            Ext.Msg.show({
                title: 'Abrir Procedimento',
                msg: 'Deseja abrir/receber este Procedimento?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function(btn) {
                    switch(btn) {
                        case 'yes':
                            this.receive_incident(record.get('pk'));
                            common.internalSecurity.incidentReport.Grid.superclass.updateItem.call(this, record)
                            break;
                        case 'no':
                            return;
                    }
                }
            });
        } else
            common.internalSecurity.incidentReport.Grid.superclass.updateItem.call(this, record)
    },

